import React, { useState } from "react";
import axios from "axios";
  // Import your custom Axios config

const CompanyRegisterForm = () => {
  const [formData, setFormData] = useState({
    name: "",
    userName: "",
    email: "",
    password: "",
    companyName: "",
    companyRole: "job_creator", // Default to job_creator
  });

  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);

    try {
       await axios.post("http://localhost:3001/user/register", {
        ...formData,
        category: "company", // Explicitly set the category
      });

      setSuccess("Company registered successfully!");
      setFormData({
        name: "",
        userName: "",
        email: "",
        password: "",
        companyName: "",
        companyRole: "job_creator",
      });
    } catch (err) {
      setError(err.response?.data?.error || "Something went wrong!");
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="text-center mb-4">Register Your Company</h2>
      <form onSubmit={handleSubmit} className="p-4 border rounded bg-light">
        {error && <div className="alert alert-danger">{error}</div>}
        {success && <div className="alert alert-success">{success}</div>}

        <div className="mb-3">
          <label htmlFor="name" className="form-label">
            Your Name
          </label>
          <input
            type="text"
            className="form-control"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="userName" className="form-label">
            Username
          </label>
          <input
            type="text"
            className="form-control"
            id="userName"
            name="userName"
            value={formData.userName}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="email" className="form-label">
            Email
          </label>
          <input
            type="email"
            className="form-control"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="password" className="form-label">
            Password
          </label>
          <input
            type="password"
            className="form-control"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="companyName" className="form-label">
            Company Name
          </label>
          <input
            type="text"
            className="form-control"
            id="companyName"
            name="companyName"
            value={formData.companyName}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="companyRole" className="form-label">
            Company Role
          </label>
          <select
            className="form-select"
            id="companyRole"
            name="companyRole"
            value={formData.companyRole}
            onChange={handleChange}
            required
          >
            <option value="job_creator">Job Creator</option>
            <option value="job_manager">Job Manager</option>
          </select>
        </div>

        <button type="submit" className="btn btn-primary w-100">
          Register
        </button>
      </form>
    </div>
  );
};

export default CompanyRegisterForm;
